def _codec72_capsule_decode(encoded):
    if type(encoded) is not str or len(encoded) != 42475:
        raise ValueError('codec72 fixed capsule encoded length differs')
    compressed = _codec72_capsule_b64.b85decode(encoded.encode('ascii', 'strict'))
    if (len(compressed) != _CODEC72_CAPSULE_PACKET['bytes']
            or _codec72_capsule_hashlib.sha256(compressed).hexdigest() != _CODEC72_CAPSULE_PACKET['sha256']
            or _codec72_capsule_b64.b85encode(compressed).decode('ascii') != encoded):
        raise ValueError('codec72 exact canonical compressed source differs')
    decoder = _codec72_capsule_zlib.decompressobj(16 + _codec72_capsule_zlib.MAX_WBITS)
    raw = decoder.decompress(compressed, _CODEC72_CAPSULE_SOURCE['bytes'] + 1)
    if (not decoder.eof or decoder.unused_data or decoder.unconsumed_tail
            or len(raw) != _CODEC72_CAPSULE_SOURCE['bytes']
            or _codec72_capsule_hashlib.sha256(raw).hexdigest() != _CODEC72_CAPSULE_SOURCE['sha256']):
        raise ValueError('codec72 source has wrong bytes, excess output, trailing data or another stream')
    raw.decode('utf-8', 'strict')
    return raw


def _codec72_capsule_load():
    raw = _codec72_capsule_decode(_CODEC72_CAPSULE_PACKET['data'])
    module = _codec72_capsule_types.ModuleType('hepta_exact_codec72_pure_source_validator_72450728')
    origin = '<embedded-current-pure-verifier-sha256:' + _CODEC72_CAPSULE_SOURCE['sha256'] + '>'
    module.__file__ = origin
    module.__embedded_original_source_pin__ = dict(_CODEC72_CAPSULE_SOURCE)
    exec(compile(raw, origin, 'exec'), module.__dict__)
    return module


